import React, { useState } from 'react';
import TopicSuggestions, { detectSuggestions } from './TopicSuggestions';

const RULED = 'repeating-linear-gradient(transparent, transparent 22px, rgba(100,80,50,0.055) 22px, rgba(100,80,50,0.055) 23px)';

// Seeded subject number from topic id
function subjectCode(id) {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (Math.imul(31, h) + id.charCodeAt(i)) | 0;
  return `MU-${String(Math.abs(h % 9999) + 1).padStart(4, '0')}`;
}

function TopicCard({ topic, thoughts, books, onSelect, children, depth = 0 }) {
  const [hovered, setHovered] = useState(false);
  const topicThoughts = thoughts.filter(t => topic.thoughtIds.includes(t.id));
  const bookIds       = [...new Set(topicThoughts.map(t => t.bookId))];
  const relatedBooks  = bookIds.map(id => books.find(b => b.id === id)).filter(Boolean);
  const lastUpdated   = new Date(topic.updatedAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
  const code          = subjectCode(topic.id);
  const isDark        = document.documentElement.getAttribute('data-theme') === 'dark';

  return (
    <div style={{ marginBottom: 0 }}>
      <div onClick={() => onSelect(topic.id)}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        style={{
          background: isDark ? '#241e14' : '#faf6ee',
          backgroundImage: depth === 0 ? RULED : 'none',
          border: `1px solid ${hovered ? 'var(--accent-2)' : 'var(--paper-3)'}`,
          borderLeft: depth === 0 ? '4px solid var(--accent-2)' : '3px solid var(--paper-3)',
          borderRadius: 2,
          padding: depth === 0 ? '14px 16px' : '10px 14px',
          cursor: 'pointer',
          position: 'relative',
          overflow: 'hidden',
          boxShadow: hovered
            ? '2px 4px 14px rgba(100,70,20,0.14)'
            : '1px 2px 5px rgba(100,70,20,0.07)',
          transition: 'box-shadow 0.15s, border-color 0.15s, transform 0.12s',
          transform: hovered ? 'translateY(-1px)' : 'none',
        }}>

        {/* Faint subject glyph watermark — depth 0 only */}
        {depth === 0 && (
          <div style={{ position: 'absolute', right: -8, bottom: -8, fontSize: 60, color: 'var(--accent-2)', opacity: 0.05, fontFamily: 'var(--font-display)', pointerEvents: 'none', userSelect: 'none', lineHeight: 1 }}>◊</div>
        )}

        {/* Subject code + classification — like a folder tab */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
          <span style={{ fontSize: 8, color: 'var(--accent)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.12em', opacity: 0.7 }}>{code}</span>
          {topic.parentId && <span style={{ fontSize: 7, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em', textTransform: 'uppercase', border: '1px solid var(--paper-3)', padding: '0px 5px', borderRadius: 2 }}>SUB-FILE</span>}
          <div style={{ flex: 1 }} />
          {/* Source dots — wax seal style */}
          {relatedBooks.map(b => (
            <div key={b.id} title={b.title} style={{ width: 7, height: 7, borderRadius: '50%', background: b.color, boxShadow: `0 0 0 1.5px ${b.color}44` }} />
          ))}
        </div>

        {/* Topic title — Playfair Display */}
        <div style={{ fontSize: depth === 0 ? 15 : 13, fontWeight: 600, color: 'var(--ink)', marginBottom: 5, lineHeight: 1.3, fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>
          {topic.title}
        </div>

        {/* Summary snippet */}
        {topic.summary && (
          <p style={{ fontSize: 12, color: 'var(--ink-3)', lineHeight: 1.6, fontStyle: 'italic', marginBottom: 8, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
            {topic.summary}
          </p>
        )}

        {/* Footer — field notes count */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, paddingTop: 6, borderTop: '1px dashed var(--paper-3)', marginTop: topic.summary ? 0 : 4 }}>
          <span style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.05em' }}>
            {bookIds.length} source{bookIds.length !== 1 ? 's' : ''} · {topicThoughts.length} field note{topicThoughts.length !== 1 ? 's' : ''}
          </span>
          <span style={{ marginLeft: 'auto', fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{lastUpdated}</span>
        </div>
      </div>

      {/* Sub-topics — indented with connector */}
      {children && (
        <div style={{ marginLeft: 16, marginTop: 4, paddingLeft: 8, borderLeft: '1px dashed var(--paper-3)', display: 'flex', flexDirection: 'column', gap: 4 }}>
          {children}
        </div>
      )}
    </div>
  );
}

export default function TopicList({ topics, thoughts, books, onSelect, onCreate, onConfirmSuggestion, dismissedTags, onDismiss }) {
  const [search, setSearch]       = useState('');
  const [filterBook, setFilterBook] = useState('all');
  const [showEmpty, setShowEmpty] = useState(false);
  const [collapsedTopics, setCollapsedTopics] = useState({});
  const toggleTopic = (id) => setCollapsedTopics(c => ({...c, [id]: !c[id]}));
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';

  const suggestions = detectSuggestions(thoughts, topics).filter(s => !dismissedTags.includes(s.tag));

  const filtered = topics.filter(t => {
    if (search && !t.title.toLowerCase().includes(search.toLowerCase())) return false;
    if (filterBook !== 'all') {
      const topicThoughts = thoughts.filter(th => t.thoughtIds.includes(th.id));
      if (!topicThoughts.some(th => th.bookId === filterBook)) return false;
    }
    if (!showEmpty && t.thoughtIds.length === 0) return false;
    return true;
  });

  const roots      = filtered.filter(t => !t.parentId);
  const getChildren = (parentId) => filtered.filter(t => t.parentId === parentId);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', background: isDark ? '#18140e' : '#f5f0e4' }}>

      {/* ── ARCHIVE HEADER ──────────────────────────────── */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '2px solid var(--paper-3)', flexShrink: 0, background: isDark ? '#1c1914' : '#e8dfc8', position: 'relative', overflow: 'hidden' }}>
        {/* Faint Elder Sign */}
        <div style={{ position: 'absolute', right: 220, top: '50%', transform: 'translateY(-50%)', fontSize: 52, color: 'var(--accent-2)', opacity: 0.06, fontFamily: 'var(--font-display)', pointerEvents: 'none', userSelect: 'none', lineHeight: 1 }}>✦</div>

        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.14em', textTransform: 'uppercase', marginBottom: 2 }}>
              Miskatonic University · Dept. of History
            </div>
            <div style={{ fontSize: 18, fontFamily: 'var(--font-display)', fontWeight: 700, color: 'var(--ink)', lineHeight: 1.2, letterSpacing: '0.01em' }}>
              Catalogue of Subjects
            </div>
            <div style={{ fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic', marginTop: 2, letterSpacing: '0.01em', fontFamily: 'var(--font-display)' }}>
              rerum cognoscere causas — {topics.length} subject{topics.length !== 1 ? 's' : ''} under investigation
            </div>
          </div>

          <div style={{ display: 'flex', gap: 6, alignItems: 'center', flexShrink: 0, flexWrap: 'wrap' }}>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search subjects…"
              style={{ width: 160, padding: '5px 10px', fontSize: 11, borderRadius: 2, fontStyle: 'italic' }} />
            <button onClick={() => onCreate()}
              style={{ fontSize: 10, padding: '6px 14px', borderRadius: 2, background: 'var(--ink)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em', whiteSpace: 'nowrap' }}>
              + OPEN FILE
            </button>
          </div>
        </div>

        {/* Filter strip */}
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 8, paddingTop: 7, borderTop: '1px dashed var(--paper-3)', flexWrap: 'wrap' }}>
          <span style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em', textTransform: 'uppercase' }}>Filter:</span>
          <select value={filterBook} onChange={e => setFilterBook(e.target.value)}
            style={{ fontSize: 10, padding: '2px 20px 2px 7px', borderRadius: 2, background: 'var(--paper-2)', color: 'var(--ink-2)', border: '1px solid var(--paper-3)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
            <option value="all">All sources</option>
            {books.map(b => <option key={b.id} value={b.id}>{b.title}</option>)}
          </select>
          <label style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 10, color: 'var(--ink-4)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
            <input type="checkbox" checked={showEmpty} onChange={e => setShowEmpty(e.target.checked)} style={{ width: 11, height: 11 }} />
            Show empty files
          </label>
        </div>
      </div>

      {/* ── CATALOGUE BODY ──────────────────────────────── */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '18px 22px' }}>
        {suggestions.length > 0 && (
          <TopicSuggestions suggestions={suggestions} thoughts={thoughts} books={books} onConfirm={onConfirmSuggestion} onDismiss={onDismiss} />
        )}

        {roots.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '70px 0', color: 'var(--ink-4)' }}>
            <div style={{ fontSize: 44, opacity: 0.08, marginBottom: 14, fontFamily: 'var(--font-display)', lineHeight: 1 }}>◊</div>
            <div style={{ fontSize: 13, fontStyle: 'italic', lineHeight: 1.85, maxWidth: 340, margin: '0 auto' }}>
              {search
                ? 'No subjects match the current search. The archive is silent on this matter.'
                : <>The catalogue holds no subjects yet.<br/><span style={{ fontSize: 10, fontFamily: 'var(--font-mono)', fontStyle: 'normal', opacity: 0.5, letterSpacing: '0.06em' }}>+ OPEN FILE to begin an inquiry.</span></>}
            </div>
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(270px, 1fr))', gap: 12 }}>
            {roots.map(topic => {
              const children = getChildren(topic.id);
              return (
                <div key={topic.id} style={{ display: 'flex', flexDirection: 'column', gap: 0 }}>
                  <TopicCard topic={topic} thoughts={thoughts} books={books} onSelect={onSelect} depth={0}>
                    {children.length > 0
                      ? children.map(c => <TopicCard key={c.id} topic={c} thoughts={thoughts} books={books} onSelect={onSelect} depth={1} />)
                      : null}
                  </TopicCard>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
